--

CREATE TABLE `planetudes` (
  `matriculeEtudiant` int(11) NOT NULL,
  `sigle` varchar(10) NOT NULL,
  `semestre` int(11) NOT NULL,
  `note` float NOT NULL DEFAULT -1,
  `cote` varchar(2) DEFAULT NULL,
  `lien` varchar(2) DEFAULT 'AV',
  `etatNote` varchar(45) DEFAULT '0',
  `annee` int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

--
-- Déchargement des données de la table `planetudes`
