--
-- Déclencheurs `planetudes`
--
DELIMITER $$
CREATE TRIGGER `before_update_planetudes` BEFORE UPDATE ON `planetudes` FOR EACH ROW BEGIN
DECLARE a, b  int;
DECLARE noteCC, noteExam, noteRT float;

SET b=2015;
SET a=1;


    
IF  OLD.etatNote='professeur'
THEN 

SET noteCC=(select  N.note from notespartielles N where N.semestre=new.semestre and N.annee=new.annee and N.sigle=OLD.sigle and N.matriculeEtudiant=OLD.matriculeEtudiant and N.idEvaluation=1);

SET noteExam=(select  N.note from notespartielles N where N.semestre=new.semestre and N.annee=new.annee and N.sigle=OLD.sigle and N.matriculeEtudiant=
OLD.matriculeEtudiant and N.idEvaluation=2);

SET noteRT=(select  N.note from notespartielles N where N.semestre=new.semestre and N.annee=new.annee and N.sigle=OLD.sigle and N.matriculeEtudiant=
OLD.matriculeEtudiant and N.idEvaluation=4);

IF (noteExam = -1 or isnull(noteExam))
THEN
SET noteExam = 0;
END IF;

IF (noteRT = -1 or isnull(noteRT))
THEN
SET noteRT = 0;
END IF;

IF (noteCC = -1 or isnull(noteCC))
THEN
SET noteCC = 0;
END IF;

IF (noteExam >= noteRT)
THEN

SET NEW.note=0.4*noteCC+0.6*noteExam;
ELSE
SET NEW.note=0.4*noteCC+0.6*noteRT;
SET NEW.lien='RT';

END IF;

END IF;
END
$$
DELIMITER ;

