--
-- Déclencheurs `sessioncourante`
--
DELIMITER $$
CREATE TRIGGER `AjtAnneUniv` BEFORE INSERT ON `sessioncourante` FOR EACH ROW Begin
set new.annee_univ = new.annee - (new.semestre % 3);
set new.semestre_reel = new.semestre %3  + 1;
end
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `MajAnneUniv` BEFORE UPDATE ON `sessioncourante` FOR EACH ROW Begin
set new.annee_univ = new.annee - (new.semestre % 3);
set new.semestre_reel = new.semestre %3  + 1;
end
$$
DELIMITER ;

