--
-- Structure de la vue `capexterne`
--
DROP TABLE IF EXISTS `capexterne`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `capexterne`  AS SELECT `b`.`idModule` AS `idModule`, `b`.`matriculeEtudiant` AS `matriculeEtudiant`, `b`.`sigle` AS `sigle`, `b`.`semestre` AS `semestre`, `b`.`note` AS `note`, 'CE' AS `capit`, `b`.`nbcredits` AS `ects` FROM `bulletinsemestriel` AS `b` WHERE `b`.`note` < 10 AND exists(select `c`.`idModule` from `compense_interne` `c` where `c`.`matriculeEtudiant` = `b`.`matriculeEtudiant` AND convert(`c`.`idModule` using utf8) = `b`.`idModule` AND `c`.`reponse` = 1 limit 1) is false AND exists(select `c`.`semestre` from `compense_externe` `c` where `c`.`matriculeEtudiant` = `b`.`matriculeEtudiant` AND `c`.`semestre` = `b`.`semestre` AND `c`.`reponse` = 1 limit 1) ;

-- --------------------------------------------------------

--
-- Structure de la vue `capexterne_bis`
--
DROP TABLE IF EXISTS `capexterne_bis`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `capexterne_bis`  AS SELECT sql_cache `p`.`module` AS `idModule`, `p`.`matriculeEtudiant` AS `matriculeEtudiant`, `p`.`sigle` AS `sigle`, `p`.`semestre` AS `semestre`, `p`.`annee` AS `annee`, `p`.`note` AS `note`, 'CE' AS `capit`, `p`.`nbCredits` AS `ects` FROM `planetudesmoduleelem_t` AS `p` WHERE `p`.`note` < 10 AND !exists(select `pp`.`matriculeEtudiant` from `planetudesmoduleelem_t` `pp` where `pp`.`note` < 7 AND `pp`.`matriculeEtudiant` = `p`.`matriculeEtudiant` AND `pp`.`module` = `p`.`module` AND `pp`.`annee` = `p`.`annee` AND `pp`.`semestre` = `p`.`semestre` limit 1) AND !exists(select `c`.`idModule` from `compense_interne_bis` `c` where `c`.`matriculeEtudiant` = `p`.`matriculeEtudiant` AND convert(`c`.`idModule` using utf8) = `p`.`module` AND `c`.`annee` = `p`.`annee` AND `c`.`semestre` = `p`.`semestre` AND `c`.`reponse` = 1 limit 1) AND exists(select `c`.`semestre` from `compense_externe_bis` `c` where `c`.`matriculeEtudiant` = `p`.`matriculeEtudiant` AND `c`.`semestre` = `p`.`semestre` AND `c`.`annee` = `p`.`annee` AND `c`.`reponse` = 1 limit 1) ;

-- --------------------------------------------------------

