-- Structure de la vue `capseul`
--
DROP TABLE IF EXISTS `capseul`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `capseul`  AS SELECT `bulletinsemestriel`.`idModule` AS `idModule`, `bulletinsemestriel`.`matriculeEtudiant` AS `matriculeEtudiant`, `bulletinsemestriel`.`sigle` AS `sigle`, `bulletinsemestriel`.`semestre` AS `semestre`, `bulletinsemestriel`.`note` AS `note`, 'C' AS `capit`, `bulletinsemestriel`.`nbcredits` AS `ects` FROM `bulletinsemestriel` WHERE `bulletinsemestriel`.`note` >= 10 ;

