--
-- Structure de la vue `carte_niveau_bac`
--
DROP TABLE IF EXISTS `carte_niveau_bac`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `carte_niveau_bac`  AS SELECT `i`.`matriculeetudiant` AS `matriculeetudiant`, concat(`e`.`prenom`,'',`e`.`nom`) AS `nom`, concat('L',max(`i`.`niveau`)) AS `niveau`, `a`.`infoBac` AS `infoBac` FROM ((`niveau_inscrits` `i` join `etudiant` `e`) join `etudesanterieures` `a`) WHERE `e`.`matriculeEtudiant` = `i`.`matriculeetudiant` AND `e`.`infoBac` = `a`.`idInfoBac` AND `i`.`matriculeetudiant` in (select `planetudes`.`matriculeEtudiant` from `planetudes` where `planetudes`.`annee` = 2022 AND `planetudes`.`semestre` = 3) GROUP BY `i`.`matriculeetudiant` ;

