--
-- Structure de la vue `cc`
--
DROP TABLE IF EXISTS `cc`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `cc`  AS SELECT `p`.`matriculeEtudiant` AS `matriculeEtudiant`, `p`.`sigle` AS `sigle`, `replaceWithZero`(ifnull(`p`.`note`,0)) AS `note`, 'CC' AS `ev`, round(`p`.`annee` MOD 100,0) * 100 + round(`p`.`annee` MOD 100,0) + 1 AS `annee`, `p`.`idEvaluation` AS `idEvaluation`, `u`.`semestre` AS `semestre`, `p`.`annee` AS `year`, `p`.`semestre` AS `semestreB` FROM ((`notespartielles_a_s` `p` join `module` `m`) join `unite` `u`) WHERE convert(`p`.`sigle` using utf8) = `m`.`sigle` AND `m`.`sigleunite` = `u`.`sigle` AND `p`.`idEvaluation` = 1 AND `p`.`semestre` = 3 ;

-- --------------------------------------------------------

--
-- Structure de la vue `cc_exam`
