DROP TABLE IF EXISTS `cc_exam`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `cc_exam`  AS SELECT `c`.`matriculeEtudiant` AS `matriculeEtudiant`, `c`.`sigle` AS `sigle`, `c`.`note` AS `noteCC`, `e`.`note` AS `noteExam`, `c`.`annee` AS `annee`, `c`.`semestre` AS `semestre`, `c`.`year` AS `year`, `c`.`semestreB` AS `semestreB` FROM (`cc` `c` left join `exam` `e` on(convert(`c`.`sigle` using utf8) = convert(`e`.`sigle` using utf8) and `c`.`matriculeEtudiant` = `e`.`matriculeEtudiant` and `c`.`semestre` = `e`.`semestre` and `c`.`annee` = `e`.`annee`)) ;

