--
-- Structure de la vue `classement`
--
DROP TABLE IF EXISTS `classement`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `classement`  AS SELECT DISTINCT `c1`.`matriculeEtudiant` AS `matriculeEtudiant`, concat(`e`.`prenom`,' ',`e`.`nom`) AS `nom`, `n`.`niveau` AS `niveau`, `n`.`idProgramme` AS `idProgramme`, `c1`.`semestre` AS `s1`, `c1`.`credits_val` AS `cered1`, `c1`.`note` AS `Moys1`, `c2`.`semestre` AS `s2`, `c2`.`credits_val` AS `cered2`, `c2`.`note` AS `Moys2`, `c3`.`semestre` AS `s3`, `c3`.`credits_val` AS `cered3`, `c3`.`note` AS `Moys3`, `c4`.`semestre` AS `s4`, `c4`.`credits_val` AS `cered4`, `c4`.`note` AS `Moys4`, `c5`.`semestre` AS `s5`, `c5`.`credits_val` AS `cered5`, `c5`.`note` AS `Moys5`, `c6`.`semestre` AS `s6`, `c6`.`credits_val` AS `cered6`, `c6`.`note` AS `Moys6`, `t`.`credits_val` AS `totalcred`, `t`.`MoyG` AS `MoyG` FROM ((((((((`total_credit_valides` `t` left join `credit_valide_sem` `c1` on(`c1`.`matriculeEtudiant` = `t`.`matriculeEtudiant` and `c1`.`semestre` = 1)) left join `credit_valide_sem` `c2` on(`t`.`matriculeEtudiant` = `c2`.`matriculeEtudiant` and `c1`.`semestre` = 1 and `c2`.`semestre` = 2)) left join `credit_valide_sem` `c3` on(`t`.`matriculeEtudiant` = `c3`.`matriculeEtudiant` and `c1`.`semestre` = 1 and `c2`.`semestre` = 2 and `c3`.`semestre` = 3)) left join `credit_valide_sem` `c4` on(`t`.`matriculeEtudiant` = `c4`.`matriculeEtudiant` and `c1`.`semestre` = 1 and `c2`.`semestre` = 2 and `c3`.`semestre` = 3 and `c4`.`semestre` = 4)) left join `credit_valide_sem` `c5` on(`t`.`matriculeEtudiant` = `c5`.`matriculeEtudiant` and `c1`.`semestre` = 1 and `c2`.`semestre` = 2 and `c3`.`semestre` = 3 and `c4`.`semestre` = 4 and `c5`.`semestre` = 5)) left join `credit_valide_sem` `c6` on(`t`.`matriculeEtudiant` = `c6`.`matriculeEtudiant` and `c1`.`semestre` = 1 and `c2`.`semestre` = 2 and `c3`.`semestre` = 3 and `c4`.`semestre` = 4 and `c5`.`semestre` = 5 and `c6`.`semestre` = 6)) join `etudiant` `e` on(`t`.`matriculeEtudiant` = `e`.`matriculeEtudiant`)) join `niveau_inscrits` `n` on(`n`.`matriculeetudiant` = `t`.`matriculeEtudiant`)) WHERE `n`.`annee` = 2017 AND `n`.`semestre` = 3 OR `n`.`annee` = 2018 AND `n`.`semestre` = 1 ORDER BY `t`.`MoyG` DESC ;

-- --------------------------------------------------------

