DROP TABLE IF EXISTS `cumulcredit`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `cumulcredit`  AS SELECT `n1`.`matriculeEtudiant` AS `matriculeEtudiant`, `n1`.`annee` AS `annee`, sum(`n2`.`ects`) AS `ects` FROM (`niveau_bis` `n1` join `niveau_bis` `n2`) WHERE `n1`.`matriculeEtudiant` = `n2`.`matriculeEtudiant` AND `n1`.`annee` >= `n2`.`annee` GROUP BY `n1`.`matriculeEtudiant`, `n1`.`annee` ORDER BY `n1`.`matriculeEtudiant` ASC, `n1`.`annee` ASC ;

