CREATE ALGORITHM=UNDEFINED DEFINER=`scolarite`@`localhost` SQL SECURITY DEFINER VIEW `viewNoteseMM2122`  AS SELECT `viewNoteseMM`.`matriculeEtudiant` AS `matriculeEtudiant`, `viewNoteseMM`.`sigle` AS `sigle`, `viewNoteseMM`.`noteExam` AS `noteExam`, `viewNoteseMM`.`noteCC` AS `noteCC`, `viewNoteseMM`.`noteRT` AS `noteRT`, `viewNoteseMM`.`annee` AS `annee` FROM `viewNoteseMM` WHERE `viewNoteseMM`.`annee` = 2223 OR `viewNoteseMM`.`annee` = 2122 AND `viewNoteseMM`.`matriculeEtudiant` in (select `notespartielles`.`matriculeEtudiant` from `notespartielles` where `notespartielles`.`annee` = 2022 AND `notespartielles`.`semestre` = 3 AND `notespartielles`.`sigle` in (select `m`.`sigle` from (`module` `m` join `unite` `u` on(`m`.`sigleunite` = `u`.`sigle` AND `u`.`semestre` = 1)))) ;

